rings-and-rods:
class Solution:
    def countPoints(self, rings: str) -> int:
        seen = {}
        for i in range(0, len(rings), 2):
            seen.setdefault(rings[i + 1], set()).add(rings[i])
        cnt = 0
        for v in seen.values():
            if len(v) == 3:
                cnt += 1
        return cnt

robot-return-to-origin:
class Solution:
    def judgeCircle(self, moves: str) -> bool:
        return moves.count('U') == moves.count('D') and moves.count('L') == moves.count('R')

row-with-maximum-ones:
class Solution:
    def rowAndMaximumOnes(self, mat: list[list[int]]) -> list[int]:
        best = -1
        idx = 0
        for i, row in enumerate(mat):
            c = sum(row)
            if c > best:
                best = c
                idx = i
        return [idx, best]

running-sum-of-1d-array:
class Solution:
    def runningSum(self, nums: list[int]) -> list[int]:
        out = []
        cur = 0
        for v in nums:
            cur += v
            out.append(cur)
        return out

score-of-a-string:
class Solution:
    def scoreOfString(self, s: str) -> int:
        total = 0
        for i in range(1, len(s)):
            total += abs(ord(s[i]) - ord(s[i - 1]))
        return total

self-dividing-numbers:
class Solution:
    def selfDividingNumbers(self, left: int, right: int) -> list[int]:
        out = []
        for n in range(left, right + 1):
            ok = True
            for c in str(n):
                if c == '0' or n % int(c) != 0:
                    ok = False
                    break
            if ok:
                out.append(n)
        return out

separate-the-digits-in-an-array:
class Solution:
    def separateDigits(self, nums: list[int]) -> list[int]:
        out = []
        for v in nums:
            for c in str(v):
                out.append(int(c))
        return out

set-mismatch:
class Solution:
    def findErrorNums(self, nums: list[int]) -> list[int]:
        n = len(nums)
        seen = [0] * (n + 1)
        for v in nums:
            seen[v] += 1
        dup = 0
        miss = 0
        for v in range(1, n + 1):
            if seen[v] == 2:
                dup = v
            elif seen[v] == 0:
                miss = v
        return [dup, miss]

shift-2d-grid:
class Solution:
    def shiftGrid(self, grid: list[list[int]], k: int) -> list[list[int]]:
        m = len(grid)
        n = len(grid[0])
        flat = [grid[i][j] for i in range(m) for j in range(n)]
        total = m * n
        k %= total
        if k:
            flat = flat[-k:] + flat[:-k]
        return [flat[i * n:(i + 1) * n] for i in range(m)]

shortest-distance-to-a-character:
class Solution:
    def shortestToChar(self, s: str, c: str) -> list[int]:
        n = len(s)
        out = [n] * n
        last = -n
        for i in range(n):
            if s[i] == c:
                last = i
            out[i] = i - last
        last = 2 * n
        for i in range(n - 1, -1, -1):
            if s[i] == c:
                last = i
            if last - i < out[i]:
                out[i] = last - i
        return out

shuffle-string:
class Solution:
    def restoreString(self, s: str, indices: list[int]) -> str:
        a = [''] * len(s)
        for i, p in enumerate(indices):
            a[p] = s[i]
        return ''.join(a)

slowest-key:
class Solution:
    def slowestKey(self, releaseTimes: list[int], keysPressed: str) -> str:
        best = releaseTimes[0]
        ans = keysPressed[0]
        for i in range(1, len(keysPressed)):
            d = releaseTimes[i] - releaseTimes[i - 1]
            if d > best or (d == best and keysPressed[i] > ans):
                best = d
                ans = keysPressed[i]
        return ans

smallest-range-i:
class Solution:
    def smallestRangeI(self, nums: list[int], k: int) -> int:
        return max(0, max(nums) - min(nums) - 2 * k)

subtract-the-product-and-sum-of-digits-o:
class Solution:
    def subtractProductAndSum(self, n: int) -> int:
        prod = 1
        total = 0
        while n:
            d = n % 10
            prod *= d
            total += d
            n //= 10
        return prod - total

thousand-separator:
class Solution:
    def thousandSeparator(self, n: int) -> str:
        s = str(n)
        out = []
        while len(s) > 3:
            out.insert(0, s[-3:])
            s = s[:-3]
        out.insert(0, s)
        return '.'.join(out)

three-consecutive-odds:
class Solution:
    def threeConsecutiveOdds(self, arr: list[int]) -> bool:
        run = 0
        for v in arr:
            if v % 2:
                run += 1
                if run == 3:
                    return True
            else:
                run = 0
        return False

three-divisors:
class Solution:
    def isThree(self, n: int) -> bool:
        cnt = 0
        d = 1
        while d * d <= n:
            if n % d == 0:
                cnt += 1 if d * d == n else 2
            d += 1
        return cnt == 3
